test('organization chart uses compact horizontal branches with scrollable overflow',async()=>{
  const css=await readFile('src/styles.css','utf8');
  assert.match(css,/#chartContents\s*\{[^}]*overflow-x:\s*auto/);
  assert.match(css,/\.org-tree,\.org-tree ul\s*\{[^}]*display:\s*flex/);
  assert.match(css,/\.org-person\s*\{[^}]*width:\s*170px/);
});

test('diagram general and service models use approved component weights',()=>{
  const baseSalary=72000000,bonusCeiling=Math.round(baseSalary*Model.monthlyRate),scores={exam:84,manager:88,routine:90,project:76};
  const result=Model.calculate({baseSalary,bonusCeiling,hasProjects:true,scores});
  assert.equal(result.policyVersion,'diagram-general-v1');assert.equal(result.performance,83.2);assert.equal(result.earned,11980800);assert.equal(result.ceiling,14400000);
  const noProject=Model.calculate({baseSalary,bonusCeiling,hasProjects:false,approvedProjectExemption:true,scores});
  assert.deepEqual(noProject.components.map(c=>c.weight),[15,15,30,40]);assert.equal(noProject.ceiling,bonusCeiling);assert.equal(noProject.performance,52.8);assert.equal(noProject.components[3].status,'scored');assert.equal(noProject.components[3].score,0);assert.equal(noProject.earned,7603200);
  assert.deepEqual(Model.calculate({baseSalary,bonusCeiling,hasProjects:false,scores}),noProject);
  const service=Model.calculate({baseSalary,bonusCeiling,policy:Model.servicePolicy,scores:{manager:90,peer:80}});
  assert.deepEqual(service.components.map(c=>c.id),['manager','peer']);assert.deepEqual(service.components.map(c=>c.weight),[40,60]);assert.equal(service.performance,84);
  assert.throws(()=>Model.calculate({baseSalary,bonusCeiling,hasProjects:true,scores:{...scores,exam:101}}));
});

test('monthly estimates and quarterly cap use distinct formulas and exact effective-date intervals',()=>{
  const month=Model.calculateMonthly({baseSalary:72000000,hasProjects:true,scores:{exam:80,manager:80,routine:80,project:80}});
  assert.equal(month.ceiling,14400000);assert.equal(month.earned,11520000);assert.equal(month.estimatedMonthly,true);assert.equal(month.finalSalary,null);
  const quarter=Model.calculateQuarterly({totalDays:90,policyVersion:'test-quarter-v1',intervals:[
    {employeeId:'e1',positionId:'p1',startDay:0,endDay:30,baseSalary:72000000,eligible:true,score:80,modelType:'general'},
    {employeeId:'e1',positionId:'p2',startDay:30,endDay:90,baseSalary:84000000,eligible:true,score:90,modelType:'services'}
  ]});
  assert.equal(quarter.complete,true);assert.equal(quarter.ceiling,48000000);assert.equal(quarter.earned,41760000);assert.equal(quarter.breakdown[0].ceiling,14400000);assert.equal(quarter.breakdown[1].earned,30240000);
  const incomplete=Model.calculateQuarterly({totalDays:90,intervals:[{startDay:0,endDay:45,baseSalary:72000000,eligible:true,score:null},{startDay:45,endDay:90,baseSalary:72000000,eligible:false,score:null}]});
  assert.equal(incomplete.complete,false);assert.equal(incomplete.earned,null);assert.equal(incomplete.knownEarned,0);
  assert.throws(()=>Model.calculateQuarterly({totalDays:90,intervals:[{startDay:0,endDay:40,baseSalary:72000000,score:80},{startDay:41,endDay:90,baseSalary:72000000,score:80}]}));
});

test('proposal harness boundary is audited, idempotent, scoped and only approval creates an assignment',async t=>{
  const dir=await mkdtemp(join(tmpdir(),'kpi-workflow-store-'));let store=openStore(dir),workflow=createWorkflow(store);
  t.after(async()=>{store.close();await rm(dir,{recursive:true,force:true});});
  const manager=workflow.user('manager-ops'),employee=workflow.user('employee-mohammad'),period=workflow.currentPeriod;
  const input={employeeId:employee.id,period,type:'indicator',category:'routine',title:'شاخص نمونه',description:'خروجی قابل بررسی',criteria:'ارائه گزارش کامل'};
  const before=workflow.snapshot(employee,employee.id).assignments.length;
  const proposal=workflow.submitProposal(manager,input);assert.equal(proposal.status,'pending');assert.equal(workflow.snapshot(employee,employee.id).assignments.length,before);
  assert.throws(()=>workflow.submitProposal(employee,input));assert.throws(()=>workflow.submitProposal(workflow.user('manager-finance'),input));
  const approved=workflow.resolveProposal(proposal.id,{status:'approved',reference:'harness-1',reason:'معیار قابل سنجش است'});assert.equal(approved.status,'approved');assert.equal(approved.events.length,2);
  assert.equal(workflow.resolveProposal(proposal.id,{status:'approved',reference:'harness-1',reason:'تکرار'}).activityId,approved.activityId);
  assert.equal(workflow.snapshot(employee,employee.id).assignments.length,before+1);assert.equal(workflow.snapshot(employee,employee.id).components[2].score,null);
  const rejected=workflow.submitProposal(manager,input);workflow.resolveProposal(rejected.id,{status:'rejected',reference:'harness-2',reason:'نیازمند تعریف بهتر'});assert.equal(workflow.snapshot(employee,employee.id).assignments.length,before+1);
  workflow.recordExamResult({employeeId:employee.id,period,score:99,reference:'exam-result-2'});assert.equal(workflow.snapshot(employee,employee.id).components[0].score,99);
  workflow.saveSurvey(manager,{employeeId:employee.id,period,score:92,note:'نسخه جدید'});
  store.close();store=openStore(dir);workflow=createWorkflow(store);
  assert.equal(workflow.snapshot(employee,employee.id).survey.score,92);assert.equal(workflow.snapshot(employee,employee.id).exam.score,99);
  assert.equal(workflow.snapshot(employee,employee.id).assignments.length,before+1);assert.equal(store.list('manager-survey',employee.id).length,4);
  assert.equal(workflow.snapshot(employee,employee.id,'1400-01').performance,null);
});

async function fixture(t){
  const dir=await mkdtemp(join(tmpdir(),'kpi-workflow-http-'));
  const server=createPanelServer({dataRoot:dir,runModel:async({prompt})=>{const evidence=JSON.parse(prompt.split('UNTRUSTED EVIDENCE:\n')[1]);return {result:{summary:'گزارش بررسی شد',criteria:[{id:'C1',status:'met',score:96,reason:'شاهد موجود است',citations:[{chunkId:evidence.chunks[0].id,quote:'completed evidence'}]}]}};}});
  server.listen(0,'127.0.0.1');await once(server,'listening');const base=`http://127.0.0.1:${server.address().port}`;
  t.after(async()=>{await new Promise(resolve=>server.close(resolve));await rm(dir,{recursive:true,force:true});});
  const account=async id=>{const initial=await(await fetch(base+'/api/session')).json();if(!id)return initial;return (await fetch(base+'/api/session',{method:'POST',headers:{'x-panel-token':initial.token},body:JSON.stringify({userId:id})})).json();};
  const request=(s,path,method='GET',data)=>fetch(base+path,{method,headers:{'x-panel-token':s.token},...(data===undefined?{}:{body:typeof data==='string'?data:JSON.stringify(data)})});
  return {dir,base,account,request};
}

test('HTTP roles isolate people and units; survey persists; fresh evidence alone updates assigned KPI',async t=>{
  const {account,request}=await fixture(t),employee=await account(),manager=await account('manager-ops'),other=await account('manager-finance');
  assert.equal((await request(employee,'/api/workflow/team')).status,403);
  assert.equal((await request(employee,'/api/workflow/employees/employee-sara')).status,403);
  assert.equal((await request(other,'/api/workflow/employees/employee-mohammad')).status,403);
  assert.equal((await request(manager,'/api/workflow/team')).status,200);
  const survey={employeeId:'employee-mohammad',period:employee.period,score:100,note:'عملکرد مناسب'};
  assert.equal((await request(employee,'/api/workflow/surveys','POST',survey)).status,403);
  assert.equal((await request(other,'/api/workflow/surveys','POST',survey)).status,403);
  assert.equal((await request(manager,'/api/workflow/surveys','POST',{...survey,score:101})).status,400);
  assert.equal((await request(manager,'/api/workflow/surveys','POST',survey)).status,201);
  let snap=await(await request(employee,'/api/workflow/me')).json();assert.equal(snap.components[1].score,100);assert.equal(snap.earned,12240000);assert.equal(snap.quarterlyPayment,false);
  const activity=snap.assignments.find(a=>a.kind==='routine'),route='/api/activities/'+activity.id;
  assert.equal((await request(other,route)).status,403);assert.equal((await request(manager,route)).status,200);
  assert.equal((await request(manager,route+'/documents?name=report.txt','POST','completed evidence')).status,403);
  assert.equal((await request(employee,route+'/documents?name=report.txt&deferReview=1','POST','completed evidence')).status,201);
  snap=await(await request(employee,'/api/workflow/me')).json();assert.equal(snap.components[2].score,null);assert.equal(snap.finalSalary,null);assert.equal(snap.earned,8352000);
  assert.equal((await request(employee,route+'/reviews','POST',{})).status,200);
  snap=await(await request(employee,'/api/workflow/me')).json();assert.equal(snap.components[2].score,96);assert.equal(snap.earned,12499200);
  await request(employee,route+'/documents?name=extra.txt&deferReview=1','POST','new evidence');snap=await(await request(employee,'/api/workflow/me')).json();assert.equal(snap.components[2].score,null);assert.equal(snap.earned,8352000);
  const proposal=await(await request(manager,'/api/workflow/proposals','POST',{employeeId:employee.user.id,period:employee.period,type:'task',category:'project',title:'کار جدید',description:'شرح خروجی',criteria:'ارائه مستند',status:'approved'})).json();assert.equal(proposal.status,'pending');assert.equal((await request(employee,'/api/workflow/proposals')).status,403);
  const freshSession=await account();assert.equal((await(await request(freshSession,'/api/workflow/me')).json()).survey.score,100);
});

